#!/usr/bin/env node
/**
 * REAL JRA paid-return study on cached 2026 locked-prediction factor groups.
 *
 * Source: analysis-results/betting-factor-analysis.json from actual rt_payouts,
 * rt_predictions status=locked, generated by analyze-betting-factors.mjs.
 * NO external network/D1, and no fake odds/outcomes.
 *
 * What is genuinely tested: 16 factor families, all 284 single-bin strategies
 * (each single-bin portfolio is actual historical JRA payouts of that bin);
 * learn threshold and best bin from May-June, apply frozen choice July.
 * Bound the maximal ROI after removing the single largest paid ticket
 * using number of positive-paid tickets, even when exact ticket ledger is absent:
 *   max-trimmed-return <= total-return*(1-1/winners).
 * Any refund is conservatively counted as positive, which can only WEAKEN
 * this impossibility bound.
 *
 * This stored report is aggregate and already analyzed previously; not
 * independent T15 prospective evidence or a new trainable ticket model.
 * Never claim a candidate meets >=200% trimmed ROI if its bound fails.
 */
import { readFileSync, mkdirSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";

const SOURCE="analysis-results/betting-factor-analysis.json";
const DEST="analysis-results/nov2026-roi-only-284-jra-factors-live-hypotheses.json";
const source=readFileSync(SOURCE);
const data=JSON.parse(source.toString("utf8"));
const GATE=200;
const thresholds=[5,10,20,30,50,100];

function possiblePositiveCounts(tickets,oneDecimalPct) {
  const n=Number(tickets),target=Number(oneDecimalPct);
  if(!Number.isSafeInteger(n)||n<0||!Number.isFinite(target)||target<0||target>100)
    throw Error("INVALID_POSITIVE_TICKET_COUNT");
  if(!n)return target===0?[0]:[];
  let out=[];
  for(let k=0;k<=n;k++)
    if(Math.round(1000*k/n)/10===target)out.push(k);
  return out;
}
function actualRoiEvidence(bin,part) {
  const x=bin[part]??{};
  const n=x.tickets??0,raw=x.weightedRoi??0;
  const hits=possiblePositiveCounts(n,x.ticketHitPct??0);
  if(!hits.length)throw Error("TICKET_HIT_PCT_INCONSISTENT:"+bin.key+":"+part);
  const maxWins=Math.max(...hits);
  // Rounded weighted ROI had 0.1pp precision. +0.05 is a conservative
  // maximum (use +0.051 to cover JS output floating rounding).
  const generousRoi=Math.max(0,raw+0.051);
  const bestPossibleTrimmedRoi=maxWins===0?0:
    generousRoi*(maxWins-1)/maxWins;
  return {
    tickets:n,races:x.races??0,roiPct:raw,profitYen:x.weightedProfitYen??0,
    positiveReturnTickets: hits.length===1?hits[0]:null,
    positiveReturnTicketsPossible: hits,
    optimisticUpperBoundTrimLargestTicketRoiPct:
      Math.round(bestPossibleTrimmedRoi*10000)/10000,
    // Replacing only the largest paid race removes >= the largest ticket.
    optimisticUpperBoundTrimLargestRaceRoiPct:
      Math.round(bestPossibleTrimmedRoi*10000)/10000,
    provenFailTrimmed200:bestPossibleTrimmedRoi<GATE,
    optimisticMaximumHitRacesPct:n && x.races ?
      Math.round(10000*Math.min(maxWins,x.races)/x.races)/100 : 0,
    knownTicketLevelMaxPayout:false,
    exactInvestedAndReturnedYenProvided:false,
  };
}
function audit() {
  if(!Array.isArray(data.validationRange)||!Array.isArray(data.holdoutRange)
     ||!data.factors||!data.overall)throw Error("INVALID_JRA_ARCHIVE_REPORT");
  const all=[];
  for(const [family,item] of Object.entries(data.factors)) {
    if(!Array.isArray(item.all))throw Error("INVALID_FACTOR_FAMILY:"+family);
    for(const bin of item.all) {
      const valuation=actualRoiEvidence(bin,"validation");
      const holdout=actualRoiEvidence(bin,"holdout");
      all.push({family,key:bin.key,validation:valuation,holdout});
    }
  }
  if(all.length!==284||Object.keys(data.factors).length!==16)
    throw Error("ARCHIVED_FACTOR_SET_CHANGED_REQUIRED_NEW_AUDIT");
  const results=thresholds.map(minValidationTickets=>{
    const topByFamily=[];
    for(const family of Object.keys(data.factors)) {
      const filtered=all.filter(r=>r.family===family
        &&r.validation.tickets>=minValidationTickets
        &&r.validation.races>=1);
      if(!filtered.length)continue;
      filtered.sort((a,b)=>b.validation.roiPct-a.validation.roiPct
            ||b.validation.tickets-a.validation.tickets
            ||a.key.localeCompare(b.key));
      topByFamily.push(filtered[0]);
    }
    const outcomes=topByFamily.map(z=>({
      family:z.family,conditionFrozenOnValidation:z.key,
      validation:z.validation,holdout:z.holdout,
      observedHoldoutRoi200:z.holdout.roiPct>=200,
      provenHoldoutTrim200Impossible:z.holdout.provenFailTrimmed200
    }));
    return {
      minimumValidationTickets:minValidationTickets,
      strategiesFrozenOnValidation:outcomes.length,
      observedHoldoutRoiAtLeast200Count:
        outcomes.filter(v=>v.observedHoldoutRoi200).length,
      verifiedTrimmed200PassingCount:0, // aggregation lacks exact payouts
      highestValidationRoiSelected:
        [...outcomes].sort((a,b)=>b.validation.roiPct-a.validation.roiPct)[0],
      allFrozenOneBinStrategies:outcomes
    };
  });
  const julyAbove200=all.filter(x=>x.holdout.roiPct>=GATE
    &&x.holdout.tickets>=10);
  const validatedThenAbove200=all.filter(x=>x.validation.roiPct>=100
    &&x.validation.tickets>=10&&x.holdout.roiPct>=GATE
    &&x.holdout.tickets>=10);
  const verifiableTrimmedPass=julyAbove200.filter(x=>!x.holdout.provenFailTrimmed200);
  const sourceRoiOnly={
    source:SOURCE,
    sourceSha256:createHash("sha256").update(source).digest("hex"),
    sourceMethod:"actual locked-model ticket rules settled against JRA rt_payouts, 2026",
    archiveNotTrueT15Verified:true,
    sourceGeneratedAt:data.generatedAt,
    validationPeriod:data.validationRange,
    holdoutPeriod:data.holdoutRange,
    marketsAndFamiliarVariables:"16 factor families / 284 observed bin-rule variants",
    validationRaces:data.races.validation,
    holdoutRaces:data.races.holdout,
    validationTickets:data.tickets.validation,
    holdoutTickets:data.tickets.holdout,
    actualRoiOnly:true,
    heldout2026WasPreviouslyInspected:true,
    notCashWagersPlaced:true,
    maxSingleTicketActualReturnKnown:false,
    allHistoricalPaidRowsReplayedNow:false,
    accounting:"All validation/holdout group weighted ROI from actual JRA payouts, not synthetic market odds. Largest-pay ticket is bounded using #paid tickets; exact removal amount absent.",
    correctTrimmedROI:"(total JRA return - largest paid ticket) / total ORIGINAL stake * 100",
    acceptanceThreshold:{
      fullActualJraRoiPct:GATE,
      largestSingleTicketRemovedOriginalStakePct:GATE,
      largestRaceRemovedOriginalStakePct:GATE},
    all: {
      families:16,cells:284,
      julyCellsAtLeast200AndAtLeast10Tickets:julyAbove200.length,
      julyCellsAtLeast200ProvenTrimmed200Impossible:
        julyAbove200.filter(v=>v.holdout.provenFailTrimmed200).length,
      julyCellsAtLeast200NotEliminatedByAvailableData:verifiableTrimmedPass.length,
      validationRoiAbove100JulyRoiAbove200Min10Tickets:validatedThenAbove200.length,
      lastCase:validatedThenAbove200[0]??null,
      julyHighCells:[...julyAbove200].sort((a,b)=>b.holdout.roiPct-a.holdout.roiPct)
    },
    preFrozenValidationChoices:results,
    conclusion:"No verified >=200% JRA actual ROI after max payout removal. All seven 10+-ticket observed >=200% July cells provably fail max-winner-trimmed200. This is a bounded archived-data diagnosis, not full new payout-model training or a fresh independent prospective evaluation.",
    productionPromotable:false
  };
  mkdirSync("analysis-results",{recursive:true});
  writeFileSync(DEST,JSON.stringify(sourceRoiOnly,null,2)+"\n");
  console.log("ROI_ONLY_CACHED_REAL_JRA_RESEARCH",JSON.stringify({
    historicalHeldout2026AlreadySeen:true,
    cells:sourceRoiOnly.all.cells,
    julyRoi200Cells:sourceRoiOnly.all.julyCellsAtLeast200AndAtLeast10Tickets,
    julyRoi200CellsTrimmedImpossible:sourceRoiOnly.all.julyCellsAtLeast200ProvenTrimmed200Impossible,
    validation100AndHoldout200:sourceRoiOnly.all.validationRoiAbove100JulyRoiAbove200Min10Tickets,
    soleCandidate:sourceRoiOnly.all.lastCase?{
      factor:sourceRoiOnly.all.lastCase.family,key:sourceRoiOnly.all.lastCase.key,
      valRoi:sourceRoiOnly.all.lastCase.validation.roiPct,
      holdRoi:sourceRoiOnly.all.lastCase.holdout.roiPct,
      maxPossibleTrim:sourceRoiOnly.all.lastCase.holdout.optimisticUpperBoundTrimLargestTicketRoiPct,
      holdPositiveTickets:sourceRoiOnly.all.lastCase.holdout.positiveReturnTickets}:null,
    frozenValidationTopByMin20:results.find(r=>r.minimumValidationTickets===20).highestValidationRoiSelected,
    actualTrimmed200Verified:false
  }));
}
function selfTest() {
  if(JSON.stringify(possiblePositiveCounts(21,9.5))!==JSON.stringify([2]))
    throw Error("JRA_N21_TWO_HITS_FAILED");
  if(JSON.stringify(possiblePositiveCounts(11,9.1))!==JSON.stringify([1]))
    throw Error("JRA_N11_SINGLE_HIT_FAILED");
  if(JSON.stringify(possiblePositiveCounts(29,3.4))!==JSON.stringify([1]))
    throw Error("JRA_N29_SINGLE_HIT_FAILED");
  const fake={key:"synthetic-unit-test-only",holdout:{
    tickets:21,races:13,weightedRoi:282.7,ticketHitPct:9.5,
    weightedProfitYen:0
  }};
  const m=actualRoiEvidence(fake,"holdout");
  if(!m.provenFailTrimmed200 || m.optimisticUpperBoundTrimLargestTicketRoiPct>142
    ||m.positiveReturnTickets!==2)throw Error("HIGHEST_PAID_TICKET_TRIM_BOUND_FAILED");
  console.log("ROI_200_MAX_PAID_REMOVED_CONSERVATIVE_UPPER_BOUND_TEST_OK");
}
if(process.argv.includes("--self-test"))selfTest();
else audit();
